  min-width: 0;
  padding: 24px 28px;
}

.dashboard-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.dashboard-card {
  padding: 8px 16px 16px;
  border-radius: 14px;
  background: var(--g-color-base-float);
