  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--g-color-base-float);
  color: var(--g-color-text-secondary);
  font-weight: 600;
  cursor: grab;
  user-select: none;
}

.dashboard-table th:active {
  cursor: grabbing;
}

.dashboard-table-select {
  width: 48px;
  cursor: default;
}

.dashboard-table tbody tr {
  transition: background .15s ease;
}

.dashboard-table tbody tr:hover {
  background: var(--g-color-base-generic-hover);
}

.dashboard-table tbody tr.selected {
  background: var(--g-color-base-selection);
}

.dashboard-group-row td {
  padding-top: 14px;
  padding-bottom: 8px;
  background: var(--g-color-base-generic);
}

.dashboard-group-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  padding: 6px 8px;
  border-radius: 8px;
  background: transparent;
  color: var(--g-color-text-primary);
  font: inherit;
  cursor: pointer;
}

.dashboard-group-toggle:hover {
  background: var(--g-color-base-generic-hover);
}

.rotated {
  transform: rotate(-90deg);
}

@media (max-width: 760px) {
  .dashboard-header {
    align-items: start;
    flex-direction: column;
  }

  .dashboard-content {
    padding: 16px;
  }
}
